"""Writes ``candlestack/ml/allowlist.py``: the Keras classes and functions an uploaded model may
name, as Keras 3.15.1 writes them into a ``config.json``.

Keras is not a dependency of the backend, so this runs in a throwaway container from the
repository root, like make_models.py:

    docker run --rm -v "$PWD/backend:/backend" python:3.13-slim sh -c \
        "pip install --quiet keras==3.15.1 jax==0.11.2 \
         && KERAS_BACKEND=jax python /backend/tests/fixtures/keras/make_allowlist.py \
            > /backend/src/candlestack/ml/allowlist.py"

Then `uv run ruff format src/candlestack/ml/allowlist.py` from backend/. A new Keras release
the worker pins regenerates it with that release.
"""

import importlib
import inspect
import sys
import types

import keras
from keras.src import api_export
from keras.src.ops.operation import Operation
from keras.src.saving import serialization_lib

KERAS = "3.15.1"

# Classes that load files, run code given to them or wrap code of another framework: never
# in a model the API accepts, whatever else the file says.
_UNSAFE_LAYERS = {
    "FlaxLayer",  # wraps a Flax module
    "IntegerLookup",  # its vocabulary may be a file path
    "JaxLayer",  # wraps a JAX function
    "Lambda",  # a Python function
    "Layer",  # the base class: a subclass is the user's code
    "StringLookup",  # its vocabulary may be a file path
    "TextVectorization",  # its vocabulary may be a file path, its standardize a function
    "TFSMLayer",  # loads a TensorFlow SavedModel from a path
    "TorchModuleWrapper",  # wraps a PyTorch module
    "Wrapper",  # a base class
}
# Operations of the functional API that take a Python function.
_UNSAFE_OPS = {
    "AssociativeScan",
    "Cond",
    "ForiLoop",
    "JVP",
    "Map",
    "Scan",
    "Switch",
    "VectorizedMap",
    "WhileLoop",
}
_OP_MODULES = ("core", "einops", "image", "linalg", "math", "nn", "numpy")


def serialized_name(obj: object) -> str:
    """`module.class_name` as Keras writes the object into a config."""
    name = api_export.get_name_from_symbol(obj)
    return name or f"{obj.__module__}.{obj.__name__}"


def classes(module: types.ModuleType, base: type, unsafe: set[str] = frozenset()) -> set[str]:
    return {
        serialized_name(obj)
        for name, obj in vars(module).items()
        if not name.startswith("_")
        and inspect.isclass(obj)
        and issubclass(obj, base)
        and obj is not base  # a subclass of the base is the user's code
        and obj.__name__ not in unsafe
    }


def functions(module: types.ModuleType) -> set[str]:
    return {
        f"{module.__name__}.{name}"
        for name, obj in vars(module).items()
        if not name.startswith("_")
        and inspect.isfunction(obj)
        and name not in {"get", "serialize", "deserialize"}
    }


def ops() -> set[str]:
    found = set()
    for name in _OP_MODULES:
        module = importlib.import_module(f"keras.src.ops.{name}")
        for obj in vars(module).values():
            if (
                inspect.isclass(obj)
                and issubclass(obj, Operation)
                and obj.__module__ == module.__name__
                and obj.__name__ not in _UNSAFE_OPS
            ):
                found.add(f"{obj.__module__}.{obj.__name__}")
    return found


def main() -> None:
    assert keras.__version__ == KERAS, keras.__version__
    allowed = (
        classes(keras.layers, keras.layers.Layer, _UNSAFE_LAYERS)
        | classes(keras.initializers, keras.initializers.Initializer)
        | classes(keras.regularizers, keras.regularizers.Regularizer)
        | classes(keras.constraints, keras.constraints.Constraint)
        | classes(keras.dtype_policies, keras.dtype_policies.DTypePolicy)
        | classes(keras.quantizers, keras.quantizers.Quantizer)
        | classes(keras.optimizers, keras.optimizers.Optimizer)
        | classes(keras.optimizers.schedules, keras.optimizers.schedules.LearningRateSchedule)
        | classes(keras.losses, keras.losses.Loss)
        | classes(keras.metrics, keras.metrics.Metric)
        # The policy every layer names; the base class of the others, unlike theirs not abstract.
        | {serialized_name(keras.DTypePolicy)}
        | {serialized_name(keras.Sequential), serialized_name(keras.src.models.Functional)}
        | ops()
    )
    allowed_functions = set().union(
        *(functions(getattr(keras, name)) for name in serialization_lib.BUILTIN_MODULES)
    )
    out = sys.stdout
    out.write(
        f'"""What an uploaded model may name: the built-in classes and functions of Keras {KERAS}\n'
        "as it writes them into a config.json (``module.class_name``), without the ones that load\n"
        "files, run code given to them or wrap another framework's code.\n\n"
        "Generated by tests/fixtures/keras/make_allowlist.py (its docstring says how to run it):\n"
        'do not edit by hand.\n"""\n\n'
    )
    out.write(f'KERAS_VERSION = "{KERAS}"\n\n')
    out.write("# Classes: layers, operations of the functional API, models, initializers,\n")
    out.write("# regularizers, constraints, dtype policies, quantizers, optimizers and their\n")
    out.write("# schedules, losses and metrics.\n")
    out.write("CLASSES = frozenset(\n    {\n")
    for name in sorted(allowed):
        out.write(f'        "{name}",\n')
    out.write("    }\n)\n\n")
    out.write(
        "# Functions an object of class ``function`` may name: every public function of the\n"
    )
    out.write(
        "# modules where Keras looks up a function by its name alone (module ``builtins``),\n"
    )
    out.write("# without get, serialize and deserialize.\n")
    out.write("FUNCTIONS = frozenset(\n    {\n")
    for name in sorted(allowed_functions):
        out.write(f'        "{name}",\n')
    out.write("    }\n)\n")


if __name__ == "__main__":
    main()
